function safestRoute(grid: number[][]): number {
  const n = grid.length;
  const dist = new Int32Array(n * n).fill(-1);
  let queue: number[] = [];
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
    if (grid[r][c] === 1) { dist[r * n + c] = 0; queue.push(r * n + c); }
  }
  const dr = [1, -1, 0, 0], dc = [0, 0, 1, -1];
  for (let h = 0; h < queue.length; h++) {
    const cur = queue[h], r = (cur / n) | 0, c = cur % n;
    for (let k = 0; k < 4; k++) {
      const nr = r + dr[k], nc = c + dc[k];
      if (nr < 0 || nc < 0 || nr >= n || nc >= n || dist[nr * n + nc] >= 0) continue;
      dist[nr * n + nc] = dist[cur] + 1;
      queue.push(nr * n + nc);
    }
  }
  const seen = new Int32Array(n * n);
  let stamp = 0;
  const canReach = (d: number): boolean => {
    if (dist[0] < d) return false;
    stamp++;
    const q = [0];
    seen[0] = stamp;
    for (let h = 0; h < q.length; h++) {
      const cur = q[h];
      if (cur === n * n - 1) return true;
      const r = (cur / n) | 0, c = cur % n;
      for (let k = 0; k < 4; k++) {
        const nr = r + dr[k], nc = c + dc[k], id = nr * n + nc;
        if (nr < 0 || nc < 0 || nr >= n || nc >= n || seen[id] === stamp || dist[id] < d) continue;
        seen[id] = stamp;
        q.push(id);
      }
    }
    return false;
  };
  let lo = 0, hi = Math.min(dist[0], dist[n * n - 1]);
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (canReach(mid)) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

