class Solution:
    def safestRoute(self, grid: List[List[int]]) -> int:
        n = len(grid)
        dist = [-1] * (n * n)
        q = deque()
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 1:
                    dist[r * n + c] = 0
                    q.append(r * n + c)
        while q:
            cur = q.popleft()
            r, c = divmod(cur, n)
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < n and 0 <= nc < n and dist[nr * n + nc] < 0:
                    dist[nr * n + nc] = dist[cur] + 1
                    q.append(nr * n + nc)

        def can_reach(d: int) -> bool:
            if dist[0] < d:
                return False
            seen = [False] * (n * n)
            seen[0] = True
            stack = [0]
            while stack:
                cur = stack.pop()
                if cur == n * n - 1:
                    return True
                r, c = divmod(cur, n)
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < n and 0 <= nc < n:
                        i = nr * n + nc
                        if not seen[i] and dist[i] >= d:
                            seen[i] = True
                            stack.append(i)
            return False

        lo, hi = 0, min(dist[0], dist[-1])
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can_reach(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

