class Solution:
    def safestRoute(self, grid: List[List[int]]) -> int:
        n = len(grid)
        dist = [[-1] * n for _ in range(n)]
        q = deque()
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 1:
                    dist[r][c] = 0
                    q.append((r, c))
        while q:
            r, c = q.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < n and 0 <= nc < n and dist[nr][nc] < 0:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))

        seen = [[False] * n for _ in range(n)]
        seen[0][0] = True
        heap = [(-dist[0][0], 0, 0)]  # negated: a max-heap on distance
        safety = dist[0][0]
        while heap:
            d, r, c = heapq.heappop(heap)
            safety = min(safety, -d)
            if r == n - 1 and c == n - 1:
                return safety
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < n and 0 <= nc < n and not seen[nr][nc]:
                    seen[nr][nc] = True
                    heapq.heappush(heap, (-dist[nr][nc], nr, nc))
        return safety

